#!/usr/bin/env bash
# Module 13 local integration verification (no OpenShift/Istio required).
set -euo pipefail
cd "$(dirname "$0")/.."

cleanup() { bash scripts/stop.sh || true; }
trap cleanup EXIT INT TERM
python3 -m compileall -q tools
python3 -m json.tool contracts/travelz-partner-v1.openapi.json >/dev/null
bash scripts/start.sh
set -a
# Generated by tools/keys.py with 0600 mode. Never source untrusted files.
. .runtime/keys.env
set +a

python3 tools/verify.py basic
python3 tools/verify.py canary
python3 tools/verify.py fallback
python3 tools/verify.py partner
python3 tools/partner_metrics.py --base-url http://127.0.0.1:5300
python3 tools/mesh_sample.py --base-url http://127.0.0.1:5100 --count 20
echo "PASS: Module 13 local Travelz, gateway, canary, fallback and quota integration"
